CREATE TABLE recovery_cases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), case_number text UNIQUE NOT NULL, user_id text NOT NULL, issue_type text NOT NULL, description text NOT NULL, amount numeric(14,2), currency text NOT NULL DEFAULT 'INR', merchant_name text, transaction_reference text, payment_method text, status text NOT NULL DEFAULT 'REPORTED', priority text NOT NULL DEFAULT 'NORMAL', confidence_score numeric(5,2), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz)